//! The panel's help cards (design/blinkenlights.md, "Where it sits and how it is called"): for each
//! instrument, lamp and readout, what it shows, what healthy looks like, and what signals trouble.

/// One help card.
pub(crate) struct Card {
    pub(crate) title: &'static str,
    pub(crate) what: &'static str,
    pub(crate) note: Option<&'static str>,
    pub(crate) good: &'static [&'static str],
    pub(crate) bad: &'static [&'static str],
}

/// The cards, by key: an instrument's name, a readout's, or `lamp:` and the lamp's.
pub(crate) fn card(key: &str) -> Option<&'static Card> {
    CARDS.iter().find(|(k, _)| *k == key).map(|(_, c)| c)
}

const fn c(title: &'static str, what: &'static str, note: Option<&'static str>, good: &'static [&'static str], bad: &'static [&'static str]) -> Card {
    Card { title, what, note, good, bad }
}

